69	 * @param {string[]} args
70	 * @param {string} [cwd]
71	 * @returns {{srcDir: string, outDir: string, i18nDir: string, englishDir: string|null}}
72	 */
73	function resolveSite(args, cwd = process.cwd()) {
74	  const i = args.indexOf('--site');
75	  if (i === -1 || !args[i + 1]) {
76	    return { srcDir: cwd, outDir: cwd, i18nDir: path.join(cwd, 'i18n'), englishDir: null };
